def main():
    import sys
    data = sys.stdin.read().strip().split()
    if not data:
        print(-1)
        return
    n = int(data[0])
    if n == 0:
        print(-1)
        return
    arr = list(map(int, data[1:n+1]))
    if len(arr) < 2:
        print(-1)
        return
    unique_sorted = sorted(set(arr), reverse=True)
    if len(unique_sorted) < 2:
        print(-1)
    else:
        print(unique_sorted[1])

if __name__ == "__main__":
    main()
